// Calculate 48-hour blocking window
// Business hours: 9 AM - 5 PM EST
// Buffer: 15 minutes between meetings

const now = new Date();

// Start from tomorrow 9 AM
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
tomorrow.setHours(9, 0, 0, 0);

// End 48 hours from now at 5 PM
const endDate = new Date(now);
endDate.setDate(endDate.getDate() + 2);
endDate.setHours(17, 0, 0, 0);

// Generate time slots to potentially block
// Each slot is 30 minutes
const slots = [];
let current = new Date(tomorrow);

while (current < endDate) {
  const hour = current.getHours();
  const day = current.getDay();

  // Skip weekends (0 = Sunday, 6 = Saturday)
  if (day !== 0 && day !== 6) {
    // Only during business hours (9 AM - 5 PM)
    if (hour >= 9 && hour < 17) {
      slots.push({
        start: new Date(current).toISOString(),
        end: new Date(current.getTime() + 30 * 60 * 1000).toISOString(),
        summary: '🔒 Focus Time (Auto-blocked)',
        description: 'Auto-blocked by MKAI Calendar Manager. Delete to open this slot for meetings.'
      });
    }
  }

  // Move to next 30-min slot
  current.setMinutes(current.getMinutes() + 30);
}

return {
  action: 'block_calendar',
  window_start: tomorrow.toISOString(),
  window_end: endDate.toISOString(),
  slots_to_check: slots.length,
  slots: slots,
  timestamp: now.toISOString()
};

// Filter out slots that already have events
// Only block slots that are currently free

const blockData = $('Calculate Block Slots').first().json;
const existingEvents = $('Get Existing Events').all().map(e => e.json);

const slotsToBlock = [];

for (const slot of blockData.slots) {
  const slotStart = new Date(slot.start);
  const slotEnd = new Date(slot.end);

  let isFree = true;

  for (const event of existingEvents) {
    const eventStart = new Date(event.start?.dateTime || event.start?.date);
    const eventEnd = new Date(event.end?.dateTime || event.end?.date);

    // Check for overlap
    if (slotStart < eventEnd && slotEnd > eventStart) {
      isFree = false;
      break;
    }
  }

  // Only add truly free slots
  if (isFree) {
    slotsToBlock.push(slot);
  }
}

return {
  total_slots: blockData.slots.length,
  existing_events: existingEvents.length,
  slots_to_block: slotsToBlock.length,
  slots: slotsToBlock
};

// Prepare slots for batch creation
const data = $input.first().json;

return data.slots.map(slot => ({
  ...slot,
  colorId: '8' // Graphite color for blocked time
}));

// Return completion summary
const filterData = $('Filter Free Slots').first().json;
const createdEvents = $input.all();

return {
  worker: 'calendar_manager',
  action: '48_hour_block',
  status: 'completed',
  total_slots_checked: filterData.total_slots,
  existing_events: filterData.existing_events,
  new_blocks_created: createdEvents.length,
  timestamp: new Date().toISOString()
};

// No slots to block - calendar already full or all blocked
const filterData = $input.first().json;

return {
  worker: 'calendar_manager',
  action: '48_hour_block',
  status: 'completed',
  message: 'No free slots to block - calendar already has events or blocks',
  total_slots_checked: filterData.total_slots,
  existing_events: filterData.existing_events,
  new_blocks_created: 0,
  timestamp: new Date().toISOString()
};
